<?php
namespace App\Services;use App\Models\{Employe,RhHoraire};use Carbon\Carbon;
class RhPresenceCalculationService {public function calculate(Employe $e,array $d):array{$zero=['heures_travaillees'=>0.0,'retard_minutes'=>0,'depart_anticipe_minutes'=>0,'heures_supplementaires'=>0.0];$h=$e->horaire?:RhHoraire::where('entreprise_id',$e->entreprise_id)->where('par_defaut',true)->first();if(!$h||empty($d['heure_arrivee']))return $zero;$date=Carbon::parse($d['date'])->toDateString();$in=Carbon::parse($date.' '.$d['heure_arrivee']);$start=Carbon::parse($date.' '.$h->heure_debut);$retard=(int)max(0,$start->diffInMinutes($in,false)-$h->tolerance_retard_minutes);if(empty($d['heure_depart']))return array_merge($zero,['retard_minutes'=>$retard]);$out=Carbon::parse($date.' '.$d['heure_depart']);$minutes=max(0,$in->diffInMinutes($out));$end=Carbon::parse($date.' '.$h->heure_fin);$early=(int)max(0,$out->diffInMinutes($end,false));$normal=(float)$h->heures_normales;return ['heures_travaillees'=>round($minutes/60,2),'retard_minutes'=>$retard,'depart_anticipe_minutes'=>$early,'heures_supplementaires'=>round(max(0,$minutes/60-$normal),2)];}}
